from itertools import permutations, product
colors='RGB'; items='KSM' # K brass coin, S silver key, M marble
# state maps visible label->item. swapping contents on object moves; swapping labels swaps state values associated? labels swap without moving boxes means items under labels swap equivalently.
init={'R':'K','G':'S','B':'M'}
overall={'R':4,'G':3,'B':3}
for lp in [('R','G'),('R','B'),('G','B')]:
 out=[]
 for order in [('K','S','M')]:
  # recurse named moves 1,2 then labels, named3, generic
  def rec(state, i, counts, ds):
   if i==2:
    st=state.copy(); a,b=lp; st[a],st[b]=st[b],st[a]
    rec(st,3,counts,ds)
    return
   if i in (0,1,3):
    item=order[0 if i==0 else 1 if i==1 else 2]
    src=next(c for c,v in state.items() if v==item)
    for dst in colors:
     if dst==src: continue
     st=state.copy(); st[src],st[dst]=st[dst],st[src]
     cc=counts.copy(); cc[src]=cc.get(src,0)+1; cc[dst]=cc.get(dst,0)+1
     rec(st,i+1,cc,ds+[(item,src,dst)])
    return
   if i==4:
    for src in colors:
     for dst in colors:
      if src==dst: continue
      cc=counts.copy(); cc[src]=cc.get(src,0)+1; cc[dst]=cc.get(dst,0)+1
      # add label occurrences
      cc[lp[0]]=cc.get(lp[0],0)+1; cc[lp[1]]=cc.get(lp[1],0)+1
      if cc==overall:
       st=state.copy(); st[src],st[dst]=st[dst],st[src]
       out.append((ds,src,dst,st))
  rec(init,0,{},[])
 print('label',lp,'solutions',len(out))
 for x in out:print(x)
PY"

